solutions.javascript:
function unikPertama(s) {
  const hitung = new Map();
  for (const ch of s) hitung.set(ch, (hitung.get(ch) || 0) + 1);
  for (let i = 0; i < s.length; i++) if (hitung.get(s[i]) === 1) return i;
  return -1;
}

