func unikPertama(s string) int {
	huruf := []rune(s)
	hitung := map[rune]int{}
	for _, ch := range huruf {
		hitung[ch]++
	}
	for i, ch := range huruf {
		if hitung[ch] == 1 {
			return i
		}
	}
	return -1
}
